<?php
require __DIR__.'/auth.php'; require_login();
$api=rtrim(getenv('MONITOR_API_URL')?:'http://api:3000','/'); $id=max(1,(int)($_GET['id']??0));
function api_get_host(string $path):array{global $api;$ch=curl_init($api.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8,CURLOPT_HTTPHEADER=>['Accept: application/json']]);$body=curl_exec($ch);curl_close($ch);return json_decode($body?:'{}',true)?:[];}
$data=api_get_host('/api/v1/hosts/'.$id);$h=$data['host']??null;$items=$data['items']??[];$alerts=$data['alerts']??[];$metrics=api_get_host('/api/v1/hosts/'.$id.'/metrics?limit=1000');if(!$h){http_response_code(404);exit('Host not found');}function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$series=[];foreach(array_reverse($metrics) as $m){if(is_numeric($m['metric_value']))$series[$m['metric_key']][]=[$m['recorded_at'],(float)$m['metric_value']];}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="30"><title><?=esc($h['name'])?> - Monitoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="index.php">Monitoring</a><a class="btn btn-outline-light btn-sm" href="index.php">Back</a></div></nav><main class="container-fluid p-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2><?=esc($h['name'])?></h2><div class="text-muted"><?=esc($h['hostname'])?> · <?=esc($h['ip_address']??$h['agent_ip']??'')?> · Agent <?=esc($h['agent_id']??'')?></div></div><span class="badge text-bg-<?=($h['status']==='ONLINE'?'success':($h['status']==='OFFLINE'||$h['status']==='CRITICAL'?'danger':'warning'))?> fs-6"><?=esc($h['status'])?></span></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="card"><div class="card-body"><small>OS</small><h5><?=esc($h['os_name']??'Unknown')?></h5><div><?=esc($h['os_release']??'')?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Agent Version</small><h5><?=esc($h['agent_version']??'-')?></h5><div>Last seen: <?=esc($h['agent_last_seen']??$h['last_seen']??'-')?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Monitoring Items</small><h5><?=count($items)?></h5></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Recent Alerts</small><h5><?=count($alerts)?></h5></div></div></div></div><div class="row g-3 mb-4"><div class="col-lg-6"><div class="card"><div class="card-header fw-semibold">CPU History</div><div class="card-body"><canvas id="cpu"></canvas></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header fw-semibold">Memory History</div><div class="card-body"><canvas id="mem"></canvas></div></div></div></div><div class="card mb-4"><div class="card-header fw-semibold">Monitoring Items</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Key</th><th>Type</th><th>Interval</th><th>Enabled</th><th>Config</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><code><?=esc($i['item_key'])?></code></td><td><?=esc($i['item_type'])?></td><td><?=esc($i['interval_sec'])?>s</td><td><?=((int)$i['enabled']?'🟢':'⚪')?></td><td><small><?=esc($i['config']??'')?></small></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-header fw-semibold">Alert History</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Severity</th><th>Status</th><th>Title</th><th>Started</th><th>Resolved</th></tr></thead><tbody><?php foreach($alerts as $a):?><tr><td><?=esc($a['severity'])?></td><td><?=esc($a['status'])?></td><td><?=esc($a['title'])?></td><td><?=esc($a['started_at'])?></td><td><?=esc($a['resolved_at']??'-')?></td></tr><?php endforeach;?></tbody></table></div></div></main><script>const s=<?=json_encode($series,JSON_UNESCAPED_SLASHES)?>;function chart(id,key){const d=s[key]||[];new Chart(document.getElementById(id),{type:'line',data:{labels:d.map(x=>x[0]),datasets:[{label:key,data:d.map(x=>x[1]),tension:.25,pointRadius:0}]},options:{responsive:true,animation:false,scales:{x:{display:false}}}})}chart('cpu','system.cpu.util');chart('mem','memory.util');</script></body></html>